// ── 6. Domain Entity with Primary Constructor ───────────────────────────────
public class Account(AccountId id, CustomerId ownerId, Money balance)
{
    public AccountId Id { get; } = id;
    public CustomerId OwnerId { get; } = ownerId;
    public Money Balance { get; private set; } = balance;

    public Result<Money, string> Deposit(Money amount)
    {
        if (amount.Amount <= 0)
            return Result<Money, string>.Fail("Deposit must be positive");

        Balance = Balance with { Amount = Balance.Amount + amount.Amount };
        return Result<Money, string>.Ok(Balance);
    }
}

// ── 7. CQRS & MediatR Request Handler ───────────────────────────────────────
public record DepositCommand(AccountId AccountId, Money Amount);

public interface IRequestHandler<in TRequest, TResponse>
{
    Task<TResponse> Handle(TRequest request, CancellationToken cancellationToken);
}

public class DepositCommandHandler(
    IUnitOfWork uow,
    IOptions<BankingOptions> options) : IRequestHandler<DepositCommand, Result<Money, string>>
{
    private readonly BankingOptions _options = options.Value;

    public async Task<Result<Money, string>> Handle(DepositCommand command, CancellationToken cancellationToken)
    {
        var account = await uow.Accounts.FindByIdAsync(command.AccountId, cancellationToken);
        if (account is null)
            return Result<Money, string>.Fail("Account not found");

        var result = account.Deposit(command.Amount);
        if (!result.IsSuccess)
            return result;

        await uow.CommitAsync(cancellationToken);
        return result;
    }
}

